function pageHeader(kicker,title,sub=""){return `<div class="eyebrow">${kicker}</div><h1 class="glitch">${title}</h1>${sub?`<p class="muted small">${sub}</p>`:""}`}
function box(title,body){return `<section class="box"><div class="section-title">[ ${title} ]</div>${body}</section>`}
function boardLink(b){return `<a href="#threads" data-board="${b.id}">${b.code}</a>`}
function threadCard(t){const b=boards.find(x=>x.id===t.board);return `<article class="thread"><div class="thread-head"><span>${t.id} // ${b?.code||"/unknown/"}</span><span>${t.date}</span></div><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.body)}</p><div class="thread-meta">${t.replies} replies · ${b?.name||"Unknown board"}</div><div class="thread-actions"><button data-action="reply" data-id="${t.id}">[ REPLY ]</button><button data-action="share" data-id="${t.id}">[ SHARE ]</button><button data-action="report" data-id="${t.id}">[ REPORT ]</button></div></article>`}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}

let toastTimer = null;
function showToast(message, kind="info"){
  let node=document.getElementById("lightinux-toast");
  if(!node){node=document.createElement("div");node.id="lightinux-toast";node.className="lightinux-toast";node.setAttribute("role","status");node.setAttribute("aria-live","polite");document.body.appendChild(node);}
  node.textContent=String(message);node.dataset.kind=kind;node.classList.add("visible");
  clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove("visible"),3200);
}
async function copyText(text){
  if(navigator.clipboard && window.isSecureContext){await navigator.clipboard.writeText(String(text));return true;}
  const area=document.createElement("textarea");area.value=String(text);area.setAttribute("readonly","");area.style.position="fixed";area.style.opacity="0";document.body.appendChild(area);area.select();
  let copied=false;try{copied=document.execCommand("copy");}catch{}area.remove();if(!copied)throw new Error("Clipboard unavailable");return true;
}

function renderHome(){return `${pageHeader("PUBLIC ACCESS NODE // 001","Welcome to the other side.","An independent underground-style community interface. No accounts or server connection in this prototype.")}<div class="intro"><b class="green">You found the entrance.</b><br>Lightinux is a small portal inspired by the early web: message boards, useful tools, terminal culture and the freedom to explore. Browse quietly. Stay curious.</div><div class="grid">${box("SYSTEM STATUS",`<div class="statline"><span>CORE</span><b class="success">OPERATIONAL</b></div><div class="statline"><span>FRONTEND</span><b>v1.0.1</b></div><div class="statline"><span>BACKEND</span><b class="muted">NOT CONNECTED</b></div><div class="statline"><span>VISITOR MODE</span><b class="success">ACTIVE</b></div><div class="statline"><span>LOCAL TIME</span><b id="home-clock">--:--:--</b></div>`)}${box("ANNOUNCEMENTS",`<p><span class="green">[INFO]</span> Lightinux is currently a frontend-only prototype.</p><p><span class="green">[NOTICE]</span> All posts and counters are demonstration data.</p><p><span class="green">[ROADMAP]</span> Backend, accounts and shared posting belong to phase two.</p>`)}</div><div class="grid">${box("LATEST THREADS",`<div class="thread-list">${threads.slice(0,3).map(threadCard).join("")}</div><p><a href="#threads">[ VIEW ALL THREADS ]</a></p>`)}${box("POPULAR BOARDS",`<div class="board-list">${[boards[4],boards[0],boards[6],boards[1]].map(b=>`<div class="statline"><span>${boardLink(b)} — ${b.name}</span><span>${b.posts.toLocaleString()} posts</span></div>`).join("")}</div><p><a href="#boards">[ EXPLORE BOARDS ]</a></p>`)}</div><div class="grid">${box("RECENT ACTIVITY",`<div class="statline"><span>/anon/ new discussion opened</span><span>just now</span></div><div class="statline"><span>/tech/ replies added</span><span>2 min ago</span></div><div class="statline"><span>/linux/ thread updated</span><span>5 min ago</span></div><div class="statline"><span>/web/ new topic</span><span>8 min ago</span></div>`)}${box("QUICK ACCESS",`<p><a href="#tools">» Open browser tools</a></p><p><a href="#tools" data-open-terminal="1">» Open interactive terminal</a></p><p><a href="#archive">» Search the archive</a></p><p><a href="#settings">» Configure interface</a></p>`)}</div>${box("LOCAL TERMINAL",terminalMarkup())}`}

function renderBoards(){return `${pageHeader("COMMUNITY INDEX // 08 BOARDS","Boards","Choose a board to explore its local demonstration threads.")}<div class="board-list">${boards.map(b=>`<div class="board-row"><div class="board-code">${b.code}</div><div><b>${b.name}</b><br><small>${b.desc}</small><br><small>Last activity: ${b.activity}</small></div><div class="count">${b.posts.toLocaleString()}<br>posts<br><a href="#threads" data-board="${b.id}">OPEN &gt;</a></div></div>`).join("")}</div>`}
function renderThreads(filter=""){const list=threads.filter(t=>!filter||t.board===filter);return `${pageHeader("LIVE DISCUSSION INDEX","Threads","Demonstration threads stored locally in this browser session.")}<div class="filterbar"><input id="thread-search" placeholder="Search title or content..." value="${escapeHTML($("#thread-search")?.value||"")}"><select id="thread-board"><option value="">All boards</option>${boards.map(b=>`<option value="${b.id}" ${filter===b.id?"selected":""}>${b.code} ${b.name}</option>`).join("")}</select><button id="thread-reset">RESET</button></div><div id="thread-results" class="thread-list">${list.map(threadCard).join("")||'<div class="empty">NO THREADS FOUND.</div>'}</div>`}
function renderArchive(){return `${pageHeader("COLD STORAGE // INDEXED","Archive","Search the local archive. Filters run entirely in your browser.")}<div class="filterbar"><input id="archive-search" placeholder="Search archived threads..."><select id="archive-board"><option value="">All categories</option>${boards.map(b=>`<option value="${b.id}">${b.code}</option>`).join("")}</select><select id="archive-date"><option value="">Any date</option><option value="2026-11-25">2026-11-25</option><option value="2026-11-24">2026-11-24</option><option value="2026-11-23">2026-11-23</option></select><button id="archive-reset">RESET</button></div><div id="archive-results" class="thread-list">${archive.map(threadCard).join("")}</div>`}

