function resourceSlug(r){return r.name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
function resourceCard(r){const saved=getFavorites();const fav=saved.includes(r.name);return `<article class="resource-card"><div class="resource-top"><span class="resource-category">${escapeHTML(r.category)}</span><span class="muted small">${escapeHTML(r.arch)}</span></div><h3><a class="resource-title-link" href="#resource/${resourceSlug(r)}">${escapeHTML(r.name)}</a></h3><button class="favorite-toggle" data-favorite="${escapeHTML(r.name)}">${fav?"[ ★ SAVED ]":"[ ☆ SAVE ]"}</button><p>${escapeHTML(r.summary)}</p><div class="resource-meta"><span><b>OS:</b> ${escapeHTML(r.systems)}</span><span><b>Licencia:</b> ${escapeHTML(r.license)}</span></div><div class="resource-links"><a href="#resource/${resourceSlug(r)}">[ OPEN TECHNICAL FILE ]</a><a href="${r.url}" target="_blank" rel="noopener noreferrer">[ OFFICIAL SITE ]</a></div></article>`}
function renderResourceDetail(slug){const r=resources.find(x=>resourceSlug(x)===slug);if(!r)return `${pageHeader("RESOURCE INDEX // NOT FOUND","Entry not found","La ficha solicitada no existe en el catálogo local.")}<p><a href="#resources">[ BACK TO RESOURCES ]</a></p>`;const t=resourceTechnical[r.name]||{purpose:r.summary,features:[],notes:"Consultá la documentación oficial para confirmar detalles específicos de la versión instalada."};const fav=getFavorites().includes(r.name);const links=[ ["OFFICIAL WEBSITE",r.url], ["DOCUMENTATION",r.docs], ...(r.repo?[["SOURCE REPOSITORY",r.repo]]:[]) ];return `${pageHeader("RESOURCE FILE // "+escapeHTML(r.category.toUpperCase()),escapeHTML(r.name),"Technical reference · Lightinux Resources 1.0.1")}<div class="resource-detail"><div class="resource-detail-head"><div><span class="resource-category">${escapeHTML(r.category)}</span><p class="resource-lead">${escapeHTML(r.summary)}</p></div><button class="favorite-toggle detail-favorite" data-favorite="${escapeHTML(r.name)}">${fav?"[ ★ SAVED ]":"[ ☆ SAVE ]"}</button></div><div class="resource-detail-grid"><section class="box"><div class="section-title">[ PURPOSE / ROLE ]</div><p>${escapeHTML(t.purpose)}</p></section><section class="box"><div class="section-title">[ TECHNICAL PROFILE ]</div><div class="resource-meta detail-meta"><span><b>Operating systems:</b> ${escapeHTML(r.systems)}</span><span><b>Architecture:</b> ${escapeHTML(r.arch)}</span><span><b>License / model:</b> ${escapeHTML(r.license)}</span><span><b>Category:</b> ${escapeHTML(r.category)}</span></div></section></div><section class="box"><div class="section-title">[ CORE CAPABILITIES ]</div>${t.features.length?`<ul class="resource-feature-list">${t.features.map(x=>`<li>${escapeHTML(x)}</li>`).join("")}</ul>`:`<p>${escapeHTML(r.summary)}</p>`}</section><section class="notice resource-caveat"><b>[ NOTES / SCOPE ]</b><br>${escapeHTML(t.notes)}</section><section class="box"><div class="section-title">[ OFFICIAL REFERENCES ]</div><div class="resource-official-links">${links.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">[ ${n} ] ↗</a>`).join("")}</div><p class="muted small">Los enlaces anteriores apuntan a sitios del proyecto o del desarrollador. Verificá allí los requisitos, licencias y versiones vigentes antes de instalar.</p></section><p><a href="#resources">[ ← BACK TO RESOURCES ]</a></p></div>`}
function renderResources(){return `${pageHeader("DIRECTORY // VERIFIED SOFTWARE","Resources","Catálogo técnico de herramientas y sistemas. Abrí cada ficha para consultar su función, perfil y referencias oficiales.")}<div class="notice small">SEGURIDAD: descargá software únicamente desde el sitio oficial o repositorios enlazados. Usá herramientas de auditoría solo en sistemas propios o con autorización.</div><div class="resource-controls"><input id="resource-search" placeholder="Buscar herramienta, categoría o función..." aria-label="Buscar recursos"><select id="resource-category"><option value="">Todas las categorías</option>${[...new Set(resources.map(r=>r.category))].map(c=>`<option>${escapeHTML(c)}</option>`).join("")}</select><span id="resource-count" class="muted small"></span></div><div id="resource-results" class="resource-grid">${resources.map(resourceCard).join("")}</div><p class="muted small">Las plataformas, licencias y arquitecturas pueden cambiar según la versión. Consultá siempre las fuentes oficiales antes de descargar.</p>`}
function knowledgeSlug(k){return k.title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
function knowledgeWordCount(k){return (k.body+" "+(k.sections||[]).map(x=>x.body).join(" ")).trim().split(/\s+/).length}
function knowledgeCard(k){return `<article class="knowledge-card"><div class="resource-top"><span class="resource-category">${escapeHTML(k.category)}</span><span class="muted small">${escapeHTML(k.level)} · ${k.readTime||"5 min"}</span></div><h3><a class="knowledge-title-link" href="#knowledge/${knowledgeSlug(k)}">${escapeHTML(k.title)}</a></h3><p>${escapeHTML(k.summary||k.body)}</p><div class="knowledge-tags">${(k.tags||[]).slice(0,4).map(t=>`<span>#${escapeHTML(t)}</span>`).join("")}</div><div class="resource-links"><a href="#knowledge/${knowledgeSlug(k)}">[ READ ARTICLE ]</a><span class="muted small">${knowledgeWordCount(k)} words</span></div></article>`}
function renderKnowledge(){return `${pageHeader("REFERENCE LIBRARY // TECHNICAL MANUAL","Knowledge","Biblioteca técnica: conceptos, fundamentos y rutas de aprendizaje con referencias primarias.")}<div class="knowledge-intro"><span class="green">[ FIELD NOTES / 1.0.1 ]</span><p>Artículos estructurados para entender cómo funcionan los sistemas, las redes y la seguridad. Cada entrada distingue conceptos, funcionamiento, límites y fuentes de consulta.</p><div class="knowledge-stats"><span><b>${knowledge.length}</b> ARTICLES</span><span><b>${new Set(knowledge.map(k=>k.category)).size}</b> CATEGORIES</span><span><b>${knowledge.reduce((n,k)=>n+(k.sections||[]).length,0)}</b> SECTIONS</span></div></div><div class="resource-controls"><input id="knowledge-search" type="search" placeholder="Buscar conceptos, protocolos, términos..." aria-label="Buscar en Knowledge"><select id="knowledge-category"><option value="">Todas las categorías</option>${[...new Set(knowledge.map(k=>k.category))].sort().map(c=>`<option>${escapeHTML(c)}</option>`).join("")}</select><span id="knowledge-count" class="muted small"></span></div><div id="knowledge-results" class="knowledge-list">${knowledge.map(knowledgeCard).join("")}</div><div class="notice small">FUENTES: estándares, documentación de proyectos y organismos técnicos. Los artículos son material educativo; consultá la especificación enlazada para implementaciones y versiones concretas.</div>`}
function renderKnowledgeDetail(slug){const index=knowledge.findIndex(k=>knowledgeSlug(k)===slug);if(index<0)return `${pageHeader("KNOWLEDGE // 404","Article not found","No existe una entrada con ese identificador en la biblioteca local.")}<p><a href="#knowledge">[ BACK TO KNOWLEDGE ]</a></p>`;const k=knowledge[index];const sections=k.sections||[{heading:"Overview",body:k.body}];const prev=knowledge[index-1],next=knowledge[index+1];return `${pageHeader("KNOWLEDGE FILE // "+escapeHTML(k.category.toUpperCase()),escapeHTML(k.title),"Technical field note · Lightinux Knowledge 1.0.1")}<div class="knowledge-detail"><div class="knowledge-detail-head"><div><span class="resource-category">${escapeHTML(k.category)}</span><span class="muted small">${escapeHTML(k.level)} · ${k.readTime||"5 min"} · ${knowledgeWordCount(k)} words</span><p class="knowledge-summary">${escapeHTML(k.summary||k.body)}</p><div class="knowledge-tags">${(k.tags||[]).map(t=>`<span>#${escapeHTML(t)}</span>`).join("")}</div></div><a class="knowledge-back" href="#knowledge">[ INDEX ]</a></div><div class="knowledge-article-layout"><aside class="knowledge-toc box"><div class="section-title">[ CONTENTS ]</div>${sections.map((s,i)=>`<button type="button" data-scroll-to="k-section-${i+1}">${String(i+1).padStart(2,"0")} // ${escapeHTML(s.heading)}</button>`).join("")}<button type="button" data-scroll-to="k-references">REF // SOURCES</button></aside><article class="knowledge-article">${sections.map((s,i)=>`<section class="knowledge-section" id="k-section-${i+1}"><div class="knowledge-section-index">SECTION ${String(i+1).padStart(2,"0")}</div><h2>${escapeHTML(s.heading)}</h2>${s.body.split("\n\n").map(par=>`<p>${escapeHTML(par)}</p>`).join("")}${s.list?`<ul class="resource-feature-list">${s.list.map(x=>`<li>${escapeHTML(x)}</li>`).join("")}</ul>`:""}${s.code?`<pre class="knowledge-code"><code>${escapeHTML(s.code)}</code></pre>`:""}</section>`).join("")}<section class="box knowledge-takeaways"><div class="section-title">[ KEY POINTS ]</div><ul class="resource-feature-list">${(k.takeaways||[]).map(x=>`<li>${escapeHTML(x)}</li>`).join("")}</ul></section><section class="box" id="k-references"><div class="section-title">[ PRIMARY REFERENCES ]</div><ol class="knowledge-sources">${k.sources.map(([n,u])=>`<li><a href="${u}" target="_blank" rel="noopener noreferrer">${escapeHTML(n)} ↗</a></li>`).join("")}</ol><p class="muted small">Referencias oficiales o estándares primarios. Fecha de consulta: noviembre de 2026. La documentación viva puede cambiar.</p></section><nav class="knowledge-pagination">${prev?`<a href="#knowledge/${knowledgeSlug(prev)}">← ${escapeHTML(prev.title)}</a>`:`<span></span>`}${next?`<a href="#knowledge/${knowledgeSlug(next)}">${escapeHTML(next.title)} →</a>`:`<a href="#knowledge">[ BACK TO INDEX ]</a>`}</nav></article></div></div>`}

function filterResources(){const q=$("#resource-search").value.toLowerCase(),c=$("#resource-category").value;const list=resources.filter(r=>(!c||r.category===c)&&`${r.name} ${r.category} ${r.summary} ${r.systems} ${r.arch} ${(resourceTechnical[r.name]?.purpose||"")} ${(resourceTechnical[r.name]?.features||[]).join(" ")}`.toLowerCase().includes(q));$("#resource-results").innerHTML=list.map(resourceCard).join("")||'<div class="empty">NO RESOURCES FOUND.</div>';$("#resource-count").textContent=`${list.length} / ${resources.length} entries`}
function filterKnowledge(){const q=$("#knowledge-search").value.toLowerCase(),c=$("#knowledge-category").value;const list=knowledge.filter(k=>(!c||k.category===c)&&`${k.title} ${k.category} ${k.body} ${k.summary||""} ${(k.tags||[]).join(" ")} ${(k.sections||[]).map(x=>x.heading+" "+x.body+" "+(x.list||[]).join(" ")).join(" ")}`.toLowerCase().includes(q));$("#knowledge-results").innerHTML=list.map(knowledgeCard).join("")||'<div class="empty">NO ARTICLES FOUND. Try another term or category.</div>';$("#knowledge-count").textContent=`${list.length} / ${knowledge.length} articles`}

