function terminalList(path){
  if(!terminalState.dirs.has(path))return null;
  const names=new Set();
  for(const d of terminalState.dirs){if(d!==path&&terminalParent(d)===path)names.add(d.split("/").pop()+"/")}
  for(const f of Object.keys(terminalState.files)){if(terminalParent(f)===path)names.add(f.split("/").pop())}
  return [...names].sort((a,b)=>a.localeCompare(b));
}
function terminalTree(path,depth=0,lines=[]){
  const entries=terminalList(path);if(!entries)return lines;
  entries.forEach((name,i)=>{const last=i===entries.length-1;lines.push("  ".repeat(depth)+(last?"└── ":"├── ")+name);if(name.endsWith("/"))terminalTree(terminalPath(name.slice(0,-1),path),depth+1,lines)});
  return lines;
}
