    if(e.key==="ArrowUp"||e.key==="ArrowDown"){e.preventDefault();if(!terminalState.history.length)return;terminalState.historyIndex=Math.max(0,Math.min(terminalState.history.length,terminalState.historyIndex+(e.key==="ArrowUp"?-1:1)));input.value=terminalState.history[terminalState.historyIndex]||"";return}
