  if($("#archive-search")){["archive-search","archive-board","archive-date"].forEach(id=>$("#"+id).addEventListener("input",filterArchive));$("#archive-reset").addEventListener("click",()=>{ $("#archive-search").value="";$("#archive-board").value="";$("#archive-date").value="";filterArchive()})}
