    $("#b64-encode").addEventListener("click",()=>{const v=$("#b64-input").value;if(!v){b64out.textContent="[ empty input ]";return}try{let bin="";new TextEncoder().encode(v).forEach(x=>{bin+=String.fromCharCode(x)});b64out.textContent=btoa(bin)}catch(e){b64out.textContent="Encoding error"}});
