  if($("#unhex-run"))$("#unhex-run").addEventListener("click",()=>{try{const h=$("#unhex-input").value.replace(/\s+/g,"");if(!h||h.length%2||!/^[0-9a-f]+$/i.test(h))throw 0;$("#unhex-output").textContent=new TextDecoder("utf-8",{fatal:true}).decode(new Uint8Array(h.match(/.{2}/g)?.map(x=>parseInt(x,16))||[]))}catch(e){$("#unhex-output").textContent="Invalid hexadecimal / UTF-8 input"}});
