  if($("#resource-search")){$("#resource-search").addEventListener("input",filterResources);$("#resource-category").addEventListener("change",filterResources)}
  if($("#knowledge-search")){$("#knowledge-search").addEventListener("input",filterKnowledge);$("#knowledge-category").addEventListener("input",filterKnowledge);$("#knowledge-category").addEventListener("change",filterKnowledge)}
