function fillBrowserInfo(){const info=[["User agent",navigator.userAgent],["Platform",navigator.platform||"Unavailable"],["Language",navigator.language],["Online",navigator.onLine?"Yes":"No"],["Screen",`${screen.width} × ${screen.height}`],["Cookies",navigator.cookieEnabled?"Enabled":"Disabled"]];$("#browser-info").innerHTML=info.map(([k,v])=>`<div class="statline"><span>${k}</span><span>${escapeHTML(v)}</span></div>`).join("")}
function readSettings(){try{const v=JSON.parse(localStorage.getItem("lightinux-settings")||"{}");if(!v||typeof v!=="object"||Array.isArray(v))return {};const d=defaults(),n=(x,lo,hi,def)=>(typeof x==="number"&&Number.isFinite(x))?Math.min(hi,Math.max(lo,x)):def,b=(x,def)=>typeof x==="boolean"?x:def;return {font:n(v.font,12,20,d.font),crt:b(v.crt,d.crt),animations:b(v.animations,d.animations),sound:b(v.sound,d.sound),glow:n(v.glow,0,100,d.glow),density:v.density==="dense"?"dense":"normal"}}catch{return {}}}
